arguments.command:
cd /app && cat > design.py <<'EOF'
import subprocess, itertools, functools
seqs={}
for blk in open('sequences.fasta').read().split('>'):
    if not blk.strip(): continue
    l=blk.strip().split('\n'); seqs[l[0].strip()]=''.join(l[1:]).upper()
o=seqs['output']; L=len(o); inp=seqs['input']
comp=str.maketrans('ACGT','TGCA')
rc=lambda s:s.translate(comp)[::-1]

@functools.lru_cache(maxsize=None)
def tm(s):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',s],capture_output=True,text=True)
    return float(r.stdout.strip())

# fragment definitions: (name, template string(circular flag), map from output pos -> template pos)
# input fragment: output[j4 .. L) + output[0..j1) ; template input circular, output pos p>=1551 -> inp[687+(p-1551)]; p<214 -> inp[p]
def in_tmpl_idx(p):
    return (687+(p-1551))%len(inp) if p>=1551 else p
frag={
 'input':dict(tmpl=inp,circ=True,map=in_tmpl_idx),
 'egfp':dict(tmpl=seqs['egfp'],circ=False,map=lambda p:p-210),
 'flag':dict(tmpl=seqs['flag'],circ=False,map=lambda p:p-921),
 'snap':dict(tmpl=seqs['snap'],circ=False,map=lambda p:p-1005),
}
# sanity of maps
for n,f in frag.items():
    if n=='input':
        assert all(f['tmpl'][in_tmpl_idx(p)]==o[p] for p in list(range(1551,L))+list(range(0,214)))
    else:
        pass
for n,rng in [('egfp',(210,924)),('flag',(924,1008)),('snap',(1008,1554))]:
    f=frag[n]
    assert all(f['tmpl'][f['map'](p)]==o[p] for p in range(*rng)), n

junc={ # (upstream frag, downstream frag, candidate a range inclusive)
 1:('input','egfp',range(206,215)),
 2:('egfp','flag',range(920,925)),
 3:('flag','snap',range(1004,1009)),
 4:('snap','input',range(1547,1555)),
}
def palind(s): return s==rc(s)
def ok_cand(a,up,dn):
    oh=o[a:a+4]
    if palind(oh): return False
    if oh.count('G')+oh.count('C') in (0,4): return False
    # downstream fwd: template base before anneal start must differ from oh[3]
    fd=frag[dn]; s=fd['map'](a+4)
    if fd['circ']: prev=fd['tmpl'][(s-1)%len(fd['tmpl'])]
    else: prev = fd['tmpl'][s-1] if s-1>=0 else None
    if prev==oh[3]: return False
    # upstream rev: template base after anneal end must differ from oh[0]
    fu=frag[up]; e=fu['map'](a)  # index just past last anneal base
    T=fu['tmpl']
    nxt = T[e%len(T)] if fu['circ'] else (T[e] if e<len(T) else None)
    if nxt==oh[0]: return False
    return True
cands={k:[o[a:a+4] for a in v[2] if ok_cand(a,v[0],v[1])] for k,v in junc.items()}
pos={k:[a for a in v[2] if ok_cand(a,v[0],v[1])] for k,v in junc.items()}
for k in junc: print(k,list(zip(pos[k],cands[k])))
EOF
python3 design.py

